def Strongest_Extension(class_name, extensions):
    strongest = []
    for ext in extensions:
        upper = 0
        lower = 0
        for l in ext:
            if l.isupper():
                upper += 1
            elif l.islower():
                lower += 1
        strength = upper - lower
        strongest.append((strength, ext))
    strongest.sort(reverse=True)
    return f'{class_name}.{strongest[0][1]}'

