def max_fill(grid, capacity):
    import math
    # Initialize variables
    num_rows = len(grid)
    num_cols = len(grid[0])
    # Iterate over rows
    total_num_drops = 0
    for row in grid:
        # Find the rightmost well that needs filling
        rightmost_well = 0
        for well_idx in range(num_cols):
            if row[well_idx] > 0:
                rightmost_well = well_idx
        # Fill all wells to the right of the rightmost one
        if rightmost_well > 0:
            # Fill up the water to the capacity
