def can_arrange(arr):
    # Highest value of any position in the array
    # If the value is <= then we can swap
    # Otherwise we increment the position counter
    # If we reach the end we return -1
    highest = 0
    count = 0
    for i in range(len(arr)):
        if arr[i] > highest:
            highest = arr[i]
        elif arr[i] <= highest:
            count += 1
        else:
            continue
        if count == len(arr):
            return -1
    return count

