        if a % 3 == 0 and b % 3 == 0:
            return min(a // 3, b // 3)
        elif a % 3 == 0 and b % 3 == 1:
            return min(a // 3, (b - 1) // 3)
        elif a % 3 == 0 and b % 3 == 2:
            return min(a // 3, (b - 2) // 3)
        elif a % 3 == 1 and b % 3 == 0:
