def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    stack = []
    group = ''
    for paren in paren_string:
        if paren == ' ':
            continue
        elif paren == '(':
            if stack:
                group += paren
            stack.append(paren)
