from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    # check if the string is empty or None
    if paren_string is None or paren_string == '':
        return []
    # check if the string contains open parens and no closing parens
    if paren_string.count('(') > paren_string.count(')'):
        raise RuntimeError('Invalid string')
    # check if the string contains closing parens and no open parens
    if paren_string.count(')') > paren_string.count('('):
        raise RuntimeError('Invalid string')
    # check if the string contains open parens and not properly closed
    if paren_string.count('(') != paren_string.count(')'):
        raise RuntimeError('Invalid string')
    # remove spaces
    paren_string = paren_string.replace(' ', '')
    # check if the string contains only parens
    if paren_string != '' and paren_string.count('(') + paren_string.count(')') != len(paren_string):
        raise RuntimeError('Invalid string')
    # check if the string only has one paren
    if len(paren_string) == 1:
        raise RuntimeError('Invalid string')
    # check if the string only has a pair of parens
    if len(paren_string) == 2:
        if paren_string == '()':
            return ['()']
        else:
            raise RuntimeError('Invalid string')
    paren_groups = []
    result = []
    for i in range(len(paren_string)):
