def histogram(test):
    # Dictionary to count character occurrences
    occurences = {}
    # Get the maximum count in the dictionary
    max_count = 0
    # Counter for each character
    for char in test:
        # Skip the space character
        if char == ' ':
            continue
        # If the character is a new one, add it
        if char not in occurences:
            occurences[char] = 1
        # Otherwise, increase the count
        else:
            occurences[char] += 1
        # Get the maximum count
        max_count = max(max_count, occurences[char])
    # Max count is zero, empty dict
    if max_count == 0:
        return {}
    # Create the result dict with the max count
    result = {}
    for char in occurences:
        if occurences[char] == max_count:
            result[char] = max_count
    return result

